def get_chain_finality(self) -> tuple[int, dict]:
    """GET /v1/chain/finality — the signed irreversible finality credential.

    The endpoint takes no query parameters (the HTTP layer rejects any
    with 400). Under one store lock the main chain and the current audit
    signer are snapshotted together. The success body has the fixed key
    order ``finalized, tip, auth``: ``finalized`` is
    ``{height, block_hash}`` naming the last **confirmed** canonical
    block (the genesis block is born confirmed), ``tip`` is the current
    chain descriptor S (identical to ``GET /v1/chain/headers``'s
    ``tip``) and ``auth`` is ``{key_version, signature}`` — an Ed25519
    signature made with the current audit signer over
    ``SHA256(UTF8("ledger-finality-v1") || canonical_json({finalized,
    tip}))``. A pending chain tip is reported in ``tip`` but never
    advances ``finalized``.
    """
    from . import light_client

    with self.store.lock:
        finalized_block = next(
            block
            for block in reversed(self.store.chain)
            if block.status == STATUS_CONFIRMED
        )
        finalized = self._anchor_descriptor(finalized_block)
        tip = self._fork_summary(self.store.chain)
        signer = self.store.audit_signer
        if signer is None:
            # Every snapshot (including migrated legacy ones) carries a
            # current audit signer after recovery; reaching here is a
            # programming error rather than a client-visible condition.
            raise RuntimeError("no audit signer available for finality")
        auth = light_client.sign_finality(
            signer["private_key"], signer["version"], finalized, tip
        )
        if auth is None:
            raise RuntimeError("current audit signer key is invalid")
        return 200, {
            "finalized": finalized,
            "tip": tip,
            "auth": auth,
        }

